function classifyCodePoint(codePoint) {
	if (codePoint <= 255) return latin1BidiTypes[codePoint];
	let lo = 0;
	let hi = nonLatin1BidiRanges.length - 1;
	while (lo <= hi) {
		const mid = lo + hi >> 1;
		const range = nonLatin1BidiRanges[mid];
		if (codePoint < range[0]) {
			hi = mid - 1;
			continue;
		}
		if (codePoint > range[1]) {
			lo = mid + 1;
			continue;
		}
		return range[2];
	}
	return "L";
}
